import{_ as p,a0 as l,w as o,s as d,I as i,x as e,a1 as a,A as t,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const z=JSON.parse('{"title":"使用 Python 調整圖像大小 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Python 調整圖像大小 | LCTT (202101) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Python 調整圖像大小 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Python 調整圖像大小 | LCTT (202101) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202101/20210101 Resize images using Python","title":"使用 Python 調整圖像大小","tag":"202101","desc":""},"relativePath":"202101/20210101 Resize images using Python.md","filePath":"[post].md"}'),g={name:"202101/20210101 Resize images using Python.md"};function h(m,s,u,f,b,y){const n=l("Link");return o(),d("div",null,[s[20]||(s[20]=i("h1",{id:"使用-python-調整圖像大小",tabindex:"-1"},[e("使用 Python 調整圖像大小 "),i("a",{class:"header-anchor",href:"#使用-python-調整圖像大小","aria-label":"Permalink to “使用 Python 調整圖像大小”"},"​")],-1)),s[21]||(s[21]=i("blockquote",null,[i("p",null,"快速解釋如何在 Python 中調整圖像大小，同時保持相同的長寬比。")],-1)),s[22]||(s[22]=i("p",null,[i("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/life-python.jpg?itok=F2PYP2wT",alt:"Python in a tree",title:"Python in a tree"})],-1)),i("p",null,[s[2]||(s[2]=e("我喜歡 ",-1)),a(n,{href:"http://python.org/",title:"Python Programming Language – Official Website"},{default:t(()=>[...s[0]||(s[0]=[e("Python",-1)])]),_:1}),s[3]||(s[3]=e("，而且我已經學了一段時間了。前段時間，我寫了一個 Python 腳本，在這個腳本中，我需要調整一堆圖片的大小，同時保持長寬比（比例）不變。於是我四處尋找，發現了 ",-1)),a(n,{href:"https://pypi.org/project/Pillow/",title:"Python Imaging Library"},{default:t(()=>[...s[1]||(s[1]=[e("Pillow",-1)])]),_:1}),s[4]||(s[4]=e("，這是一個 Python 圖像庫，也是一個叫做 PIL 的舊庫的“友好復刻”。",-1))]),s[23]||(s[23]=r(`<p>要安裝 Pillow，請使用 Python 的 <code>pip</code> 模組：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ python3 -m pip install Pillow</span></span></code></pre></div><h3 id="按寬度縮放" tabindex="-1">按寬度縮放 <a class="header-anchor" href="#按寬度縮放" aria-label="Permalink to “按寬度縮放”">​</a></h3><p>這是一個使用 Pillow 模組來調整圖片大小的基本腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>basewidth = 300</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>wpercent = (basewidth / float(img.size[0]))</span></span>
<span class="line"><span>hsize = int((float(img.size[1]) * float(wpercent)))</span></span>
<span class="line"><span>img = img.resize((basewidth, hsize), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>這幾行 Python 代碼使用 Pillow 將一張圖片 （<code>fullsized_image.jpg</code>） 調整為 300 像素的寬度，寬度在變量 <code>basewidth</code> 中設置，高度則與新的寬度成比例。比例高度的計算方法是：確定 300 像素佔原寬度 （<code>img.size[0]</code>） 的百分比，然後將原高度（<code>img.size[1]</code>） 乘以該百分比。所得的高度值保存在變量 <code>hsize</code> 中。</p><p>如果你需要不同的圖片寬度，你可以將 <code>basewidth</code> 改為任何其他數字。另外，請注意，因為我想保留全尺寸的圖片 （<code>fullsized_image.jpg</code>），因此我將調整後的圖片以一個不同的名稱 <code>resized_image.jpg</code> 保存。當然，你不必這麼做。如果你想，你可以使用相同的文件名將調整後的圖片覆蓋全尺寸的圖片。</p><h3 id="按高度縮放" tabindex="-1">按高度縮放 <a class="header-anchor" href="#按高度縮放" aria-label="Permalink to “按高度縮放”">​</a></h3><p>如果高度是固定的，而寬度是按比例變化的，那也基本差不多，你只需要把東西換一下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>from PIL import Image</span></span>
<span class="line"><span></span></span>
<span class="line"><span>baseheight = 560</span></span>
<span class="line"><span>img = Image.open(&#39;fullsized_image.jpg&#39;)</span></span>
<span class="line"><span>hpercent = (baseheight / float(img.size[1]))</span></span>
<span class="line"><span>wsize = int((float(img.size[0]) * float(hpercent)))</span></span>
<span class="line"><span>img = img.resize((wsize, baseheight), Image.ANTIALIAS)</span></span>
<span class="line"><span>img.save(&#39;resized_image.jpg&#39;)</span></span></code></pre></div><p>注意 <code>basewidth</code> 現在換成了 <code>baseheight</code>，因為高度是固定的。在第三行中，我們在計算高度百分比，所以我們需要 <code>img.size[1]</code> 而不是 <code>img.size[0]</code>。<code>size</code> 屬性是一個元組，包含寬度和高度，單位是像素，<code>size[0]</code> 指的是第一個元組元素，也就是寬度，<code>size[1]</code> 是第二個元素，也就是高度。第 4 行也有這樣的切換，<code>size[0]</code> 代表寬度，<code>size[1]</code> 代表高度。</p><hr>`,12)),i("p",null,[s[6]||(s[6]=e("via: ",-1)),a(n,{href:"https://opensource.com/life/15/2/resize-images-python"},{default:t(()=>[...s[5]||(s[5]=[e("https://opensource.com/life/15/2/resize-images-python",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/dayontwari"},{default:t(()=>[...s[7]||(s[7]=[e("Dayo Ntwari",-1)])]),_:1}),s[12]||(s[12]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[e("lujun9972",-1)])]),_:1}),s[13]||(s[13]=e(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[9]||(s[9]=[e("geekpi",-1)])]),_:1}),s[14]||(s[14]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[e("LCTT",-1)])]),_:1}),s[18]||(s[18]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[e("Linux中國",-1)])]),_:1}),s[19]||(s[19]=e(" 榮譽推出",-1))])])}const c=p(g,[["render",h]]);export{z as __pageData,c as default};
